html:
{%- import "altor_project/templates/print/altor_print.html" as ap with context -%}
{%- set c = altor_company(doc.company, doc) -%}
{{ ap.styles(c) }}
<div class="ap">
{{ ap.header(c, "ASSET RETURN NOTE", "إذن إرجاع معدات", [
    ["Return No.", doc.name],
    ["Return Date", ap.date(doc.return_date)],
    ["Return / Gate Pass", doc.return_ref],
    ["Allocation", doc.asset_allocation]
]) }}
{{ ap.two_boxes(
    ap.info_box("Project", [["Project", doc.project], ["Name", doc.project_name], ["Division", doc.cost_center], ["Delivered On", ap.date(doc.delivery_date)]]),
    ap.info_box("Cost to the Project", [["Depreciation", ap.amt(doc.total_depreciation)], ["Damage Cost", ap.amt(doc.total_damage_cost)], ["Total", ap.amt(doc.total_cost)]])
) }}
<table class="items">
  <thead><tr><th style="width:4%">#</th><th>Asset</th><th>UOM</th><th class="right">On Site</th><th class="right">Returned (Good)</th><th class="right">Damaged / Lost</th>
  <th class="right">Days</th><th class="right">Depreciation</th><th class="right">Damage Cost</th></tr></thead>
  <tbody>
  {%- for r in doc.get("items") %}
  <tr><td>{{ loop.index }}</td><td><span class="item-name">{{ r.asset_name }}</span><div class="muted">{{ r.project_asset }}</div>{% if r.damage_remarks %}<div class="muted">{{ r.damage_remarks }}</div>{% endif %}</td>
    <td>{{ r.uom or "" }}</td><td class="right">{{ ap.num(r.on_site_qty) }}</td><td class="right"><b>{{ ap.num(r.returned_qty) }}</b></td>
    <td class="right">{% if r.damaged_qty %}<b style="color:#b42318">{{ ap.num(r.damaged_qty) }}</b>{% else %}0{% endif %}</td>
    <td class="right">{{ r.days }}</td><td class="right">{{ ap.amt(r.depreciation_amount) }}</td><td class="right">{{ ap.amt(r.damage_cost) }}</td></tr>
  {%- endfor %}
  <tr class="sub"><td colspan="4">Total</td><td class="right">{{ ap.num(doc.total_returned_qty) }}</td><td class="right">{{ ap.num(doc.total_damaged_qty) }}</td><td></td>
    <td class="right">{{ ap.amt(doc.total_depreciation) }}</td><td class="right">{{ ap.amt(doc.total_damage_cost) }}</td></tr>
  </tbody>
</table>
{{ ap.section("Remarks", doc.remarks and doc.remarks | replace("\n", "<br>")) }}
{{ ap.signatures(c, ["Returned by (Site)", "Received by (Store)", "Checked by"], 9) }}
{{ ap.footer(c) }}
</div>
